import { ImageResponse } from 'next/og'

export const alt = 'Preview'
export const size = { width: 1200, height: 630 }
export const contentType = 'image/png'
export const runtime = 'nodejs'

// OG images are pre-generated by Cloud Functions on publish/republish and
// stored as `ogImageUrl` in published_projects. This route is a fallback only.
export default function Image() {
  return new ImageResponse(
    <div style={{ display: 'flex', width: '100%', height: '100%', background: '#111' }} />,
    size,
  )
}

